import pathlib,json,hashlib,runpy
P=pathlib.Path(__file__).parent;R=P.parent/'banpo-riche-101-representative';sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest();d=json.loads((P/'final-binding-proof.json').read_text());assert len(d['results'])==9 and all(x['reload_pass'] and x['glb_unchanged'] for x in d['results']);h=json.loads((P/'binding-preserved-bytes.json').read_text());assert len(h)==45 and all(sha(pathlib.Path(k))==v for k,v in h.items());(P/'binding-byte-preservation-proof.json').write_text(json.dumps({'glbs':9,'renders':36,'all_bytes_unchanged':True,'hashes':h},indent=2))
for n in ['mcp-final-bindings-reload.json','final-binding-proof.json','binding-byte-preservation-proof.json','binding-map-frozen.json']:(R/n).write_bytes((P/n).read_bytes())
# Keep existing visual and source research review statements; update bundle actual metadata hashes.
a=json.loads((R/'bundle.json').read_text());s=json.loads((R/'source-data.json').read_text());a[0].update(supersedesAssetIds=s['supersedesAssetIds'],binding_status=s['binding_status'],sourceSha256=sha(R/'source-data.json'),blendSha256=sha(R/'banpo-riche-101-authored.blend'));(R/'bundle.json').write_text(json.dumps(a,ensure_ascii=False,indent=2));(R/'final-hashes.json').write_text(json.dumps({str(f.relative_to(R)):sha(f) for f in R.rglob('*') if f.is_file() and f.name!='final-hashes.json'},indent=2));runpy.run_path(str(P/'finalize.py'))
for p,f in [(P,'bundle-hashes.json'),(R,'final-hashes.json')]:
 h=json.loads((p/f).read_text());assert all(sha(p/k)==v for k,v in h.items());print(p.name,len(h),'final hashes verified')
